What does this code do?

```javascript
const people = [
  { id: 1, name: 'Ada' },
  { id: 2, name: 'Grace' }
];

function App() {
  return (
    <div>
      {people.map(person => (
        <p key={person.id}>{person.name}</p>
      ))}
    </div>
  );
}
```
